/* chapter picker */
.chapter-screen{min-height:calc(100vh - 74px);padding:54px 10.1% 42px;position:relative}.chapter-screen-head .back-button{margin-bottom:30px}.chapter-screen-head h2{font-size:65px;margin:21px 0 12px}.chapter-screen-head>p{margin:0;color:#77807b;font-size:14px}.chapter-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:39px 0 64px}.chapter-card{position:relative;text-align:left;border:1px solid #d5d3c8;background:#f9f7ef;padding:21px 20px 19px;min-height:158px;cursor:pointer;color:var(--ink);transition:transform .2s,border-color .2s,background .2s}.chapter-card:hover{transform:translateY(-4px);border-color:#87988a;background:white}.chapter-card-top{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.1em;color:#929890}.chapter-card-icon{height:29px;width:29px;display:grid;place-items:center;background:#e9e9d3;color:#526c60;border-radius:50%;font-size:15px}.chapter-card:nth-child(2n) .chapter-card-icon{background:#f3e0d8;color:#cb6e57}.chapter-card h3{font:600 19px var(--display);letter-spacing:-.04em;margin:17px 0 5px}.chapter-card p{font-size:11px;color:#858b83;margin:0}.chapter-card-arrow{position:absolute;right:18px;bottom:17px;font-size:17px;color:#dc765f}.chapter-screen-footer{position:absolute;bottom:23px;left:10.1%;right:10.1%;display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.09em;color:#92968e}
