.game-screen{min-height:calc(100vh - 74px);display:grid;grid-template-columns:242px 1fr}.sidebar{background:#e8e4d8;padding:26px 23px 20px 34px;display:flex;flex-direction:column;min-height:calc(100vh - 74px);position:relative}.back-button{display:flex;align-items:center;gap:9px;border:0;background:transparent;padding:0;color:#80867e;font:9px var(--mono);letter-spacing:.08em;cursor:pointer;width:max-content}.back-button:hover{color:var(--ink)}.back-button span{font-size:16px;color:#e2765f}.chapter-label{font:9px var(--mono);letter-spacing:.09em;color:#93978d;margin-top:57px}.chapter-name{font:600 24px/1.1 var(--display);letter-spacing:-.05em;margin-top:8px}.chapter-index{font:9px var(--mono);letter-spacing:.1em;color:#9a9e94;margin-top:9px}.sidebar-rule{border-top:1px solid #ceccc0;margin:29px 0 24px}.progress-heading{display:flex;justify-content:space-between;font:9px var(--mono);letter-spacing:.06em;color:#898f85}.progress-heading span:last-child{color:#39473e}.progress-track{height:4px;background:#d5d4c8;margin-top:13px;overflow:hidden}.progress-track>div{height:100%;background:#81a189;width:20%;transition:width .35s}.progress-dots{display:flex;justify-content:space-between;margin-top:10px}.progress-dots span{height:5px;width:5px;border:1px solid #aeb1a6;border-radius:50%}.progress-dots span.done{background:#80a088;border-color:#80a088}.sidebar-bottom{margin-top:auto}.streak-badge{display:flex;align-items:center;gap:11px}.streak-icon{font-size:22px;color:#df775d}.streak-badge div{display:flex;align-items:baseline;gap:7px}.streak-number{font:600 18px var(--display)}.streak-caption{font:8px var(--mono);letter-spacing:.08em;color:#92968c}.sidebar-tip{background:#dedfd0;padding:13px 13px 12px;margin:19px 0 22px;display:flex;gap:10px;align-items:flex-start}.tip-star{color:#e4775d;font-size:15px}.sidebar-tip p{font-size:11px;line-height:1.55;color:#707a70;margin:0}.chapter-switch{padding-top:13px;border-top:1px solid #ceccc0;display:flex;justify-content:space-between;align-items:center;font:8px var(--mono);letter-spacing:.08em;color:#8c9188}.chapter-switch button{height:25px;width:25px;border:1px solid #c8c8bc;background:transparent;color:#db745e;cursor:pointer;font-size:15px}.game-main{padding:25px 6.7% 18px;display:flex;flex-direction:column;min-width:0}.game-topline{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);letter-spacing:.1em;color:#8e938a}.breadcrumb-muted{color:#a1a39a}.crumb-slash{margin:0 10px;color:#c5c3b9}.game-topline #crumb-chapter{color:#4d5b52}.score-pill{border:1px solid #d9d7cc;padding:8px 11px;display:flex;align-items:center;gap:6px;color:var(--ink)}.score-star{color:#df765e;font-size:12px}.score-label{font-size:8px;color:#8a9088;margin-left:3px}.question-area{margin:39px 0 22px}.question-kicker{display:flex;align-items:center;gap:10px;font:9px var(--mono);letter-spacing:.11em;color:#8c9389}.question-number{color:#df765e}.kicker-dash{width:20px;border-top:1px solid #c4c3b9}.question-text{font:600 clamp(24px,3vw,37px)/1.2 var(--display);letter-spacing:-.055em;max-width:700px;margin:14px 0 10px}.instruction{color:#8a9187;font-size:12px}.instruction-icon{font-size:17px;color:#d7735c;padding-right:6px}.doors-grid{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:13px;margin:auto 0 22px;min-height:257px}.answer-door{border:1px solid #d6d3c8;background:#eeece2;position:relative;display:flex;flex-direction:column;align-items:center;padding:12px 9px 12px;cursor:pointer;color:var(--ink);text-align:center;transition:transform .18s,border .18s,background .18s;overflow:hidden}.answer-door:hover{transform:translateY(-5px);border-color:#799182;background:#e7e9dc}.answer-door:focus-visible,.chapter-card:focus-visible,.primary-button:focus-visible{outline:2px solid #55796a;outline-offset:3px}.door-number-small{align-self:flex-start;color:#999d92;font:9px var(--mono);letter-spacing:.08em;z-index:1}.door-arch{position:relative;margin:15px auto 0;width:min(100%,117px);height